func newInventoryPreloadsDeleteAllCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagYes    bool
		flagDryRun bool
	)

	cmd := &cobra.Command{
		Use:   "delete-all",
		Short: "Delete all Inventory Preload records",
		Long:  "Deletes all Inventory Preload records.",
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Confirmation for destructive action
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "Would delete-all\n")
				return nil
			}
			if !flagYes {
				noInput, _ := cmd.Flags().GetBool("no-input")
				if noInput {
					return fmt.Errorf("destructive operation requires --yes when --no-input is set")
				}
				fmt.Fprintf(os.Stderr, "⚠️  This will delete-all. Type 'yes' to confirm: ")
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			// Destructive cooldown enforcement
			noInputCooldown, _ := cmd.Flags().GetBool("no-input")
			if err := cooldown.Enforce(ctx.ProfileName, noInputCooldown, ctx.DestructiveCooldown); err != nil {
				return err
			}

			// Build request path
			path := "/v2/inventory-preload/records/delete-all"

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			// Read body from stdin if available
			var body io.Reader
			var normalized []byte
			stat, _ := os.Stdin.Stat()
			if (stat.Mode() & os.ModeCharDevice) == 0 {
				raw, err := io.ReadAll(io.LimitReader(os.Stdin, 10<<20))
				if err != nil {
					return fmt.Errorf("reading stdin: %w", err)
				}
				normalized, err = normalizeInputToJSON(raw)
				if err != nil {
					return err
				}
			}
			if len(normalized) > 0 {
				body = bytes.NewReader(normalized)
			}
			resp, err := ctx.Client.Do(reqCtx, "POST", path, body)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			err = ctx.Output.PrintResponse(resp)
			if err == nil && resp.StatusCode >= 200 && resp.StatusCode < 300 {
				cooldown.Record(ctx.ProfileName)
			}
			return err
		},
	}

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")

	return cmd
}

func newInventoryPreloadsCsvValidateCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagFile string
	)

	cmd := &cobra.Command{
		Use:   "csv-validate",
		Short: "Validate a given CSV file",
		Long:  "Validate a given CSV file. Serial number and device type are required. All other fields are optional. A CSV template can be downloaded from '/v2/inventory-preload/csv-template'.",
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Build request path
			path := "/v2/inventory-preload/csv-validate"

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			if ctx.Uploader == nil {
				return fmt.Errorf("file upload not supported in this context")
			}
			f, err := os.Open(flagFile)
			if err != nil {
				return fmt.Errorf("opening %s: %w", flagFile, err)
			}
			defer f.Close()
			// Stream the file through a seekable multipart body so Upload can
			// precompute Content-Length and retry on HTTP 429 without
			// re-buffering the file.
			body, contentType, contentLength, err := client.NewMultipartFileUpload("file", f)
			if err != nil {
				return fmt.Errorf("building multipart body: %w", err)
			}
			resp, err := ctx.Uploader.Upload(reqCtx, path, body, contentType, contentLength)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&flagFile, "file", "", "Path to file to upload (required)")
	_ = cmd.MarkFlagRequired("file")

	return cmd
}

