func newInventoryPreloadsApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile     string
		flagYes      bool
		flagDryRun   bool
		flagScaffold bool
	)

	cmd := &cobra.Command{
		Use:   "apply",
		Short: "Create or replace a inventory-preload by name",
		Long: `Create or replace a inventory-preload. Reads JSON or YAML from --from-file or stdin.

The name field in the input is used to check if the resource
already exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.`,
		Example: `  # Apply a inventory-preload from a JSON file
  jamf-cli pro inventory-preloads apply --from-file inventory-preload.json

  # Apply a inventory-preload from a YAML file
  jamf-cli pro inventory-preloads apply --from-file inventory-preload.yaml

  # Apply from stdin
  cat inventory-preload.json | jamf-cli pro inventory-preloads apply

  # Apply without replacement confirmation
  jamf-cli pro inventory-preloads apply --from-file inventory-preload.json --yes

  # Preview what would happen
  jamf-cli pro inventory-preloads apply --from-file inventory-preload.json --dry-run`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			reqCtx := cmd.Context()
			if flagScaffold {
				return printScaffoldOutput(`{
  "appleCareId": 5678,
  "assetTag": "ABCDEFG12345",
  "barCode1": 123456789,
  "barCode2": 123456789,
  "building": "Eau Claire",
  "department": "IT",
  "deviceType": "Computer",
  "emailAddress": "ITBob@jamf.com",
  "extensionAttributes": [],
  "fullName": "Name",
  "leaseExpiration": "2015-06-19T00:00:00Z",
  "lifeExpectancy": "5 years",
  "phoneNumber": "555-555-5555",
  "poDate": "2019-02-04T21:09:31.661Z",
  "poNumber": 8675309,
  "position": "IT Team Lead",
  "purchasePrice": "$399",
  "purchasingAccount": "IT Budget",
  "purchasingContact": "Nick in IT",
  "room": "4th Floor - Quad 3",
  "serialNumber": "C02L29ECF8J1",
  "username": "admin",
  "vendor": "Apple",
  "warrantyExpiration": "2012-07-21T00:00:00Z"
}`, ctx.Output.Format())
			}

			// Read input (JSON or YAML). When file flags are present, empty input
			// is OK — the file-field injector constructs a minimal body.
			data, err := readApplyInput(fromFile)
			if err != nil {
				return err
			}
			if len(data) > 0 {
				data, err = normalizeInputToJSON(data)
				if err != nil {
					return err
				}
			}

			// Extract name from JSON input
			name, err := extractJSONField(data, "name")
			if err != nil {
				return fmt.Errorf("input must include a %q field: %w", "name", err)
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveNameToIDForApply(reqCtx, ctx.Client, "/v2/inventory-preload/records", "name", "id", name, noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create
				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create inventory-preload %q\n", name)
					return nil
				}
				resp, err := ctx.Client.Do(reqCtx, "POST", "/v2/inventory-preload/records", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				fmt.Fprintf(os.Stderr, "Created inventory-preload %q\n", name)
				return ctx.Output.PrintResponse(resp)
			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace inventory-preload %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("inventory-preload %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "inventory-preload %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			updatePath := strings.Replace("/v2/inventory-preload/records/{id}", "{id}", url.PathEscape(id), 1)
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced inventory-preload %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON or YAML input file (or pipe to stdin)")
	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")

	return cmd
}
